const ts = Date.now();
const rand = Math.floor(Math.random()*10000);
pm.collectionVariables.set("postTitle", "Test Post " + ts + "_" + rand);
pm.collectionVariables.set("postContent", "This is test post content created at " + new Date().toISOString());

pm.test("Create Post - Status code is 201", function () { 
    pm.response.to.have.status(201); 
});

pm.test("Create Post - Response has post object", function () {
    const json = pm.response.json();
    pm.expect(json.message).to.eql("Post created successfully");
    pm.expect(json.post).to.have.property("id");
    pm.expect(json.post.title).to.eql(pm.collectionVariables.get("postTitle"));
    pm.expect(json.post.content).to.eql(pm.collectionVariables.get("postContent"));
    pm.expect(json.post).to.have.property("user_id");
});

pm.test("Save post ID for later", function () {
    const json = pm.response.json();
    if (json.post && json.post.id) pm.collectionVariables.set("postId", json.post.id);
});

