    method: 'POST',
    header: { 'Content-Type': 'application/json' },
    body: { mode: 'raw', raw: JSON.stringify({ 
        title: "No Token Post", 
        content: "This should fail", 
        author: "unauthorized" 
    }) }
}, function (err, res) {
    pm.test("Create Post No Token - Status code is 401", function () { 
        pm.expect(res.code).to.eql(401); 
    });
